 return `<nav class="event-nav" aria-label="Navegação histórica"><a href="#cronologia?era=${encodeURIComponent(event.era)}">← ${event.era==='Antes da contagem'?'Cronologia anterior às eras':'Cronologia da '+esc(event.era)+' Era'}</a><span>${esc(event.id)} · ${esc(event.kind)}</span><a href="#cronologia?q=${encodeURIComponent(event.title)}">Ver este marco na cronologia ↗</a></nav>`;
