 const list=allowed.filter(r=>(!f.person||r.fromId===f.person||r.toId===f.person)&&(!f.type||r.type===f.type)&&(!f.q||norm([orgEntity(r.fromId)?.name,orgEntity(r.toId)?.name,r.description,r.period].join(' ')).includes(norm(f.q))));
 const ids=new Set(allowed.flatMap(r=>[r.fromId,r.toId])),people=org.entities.filter(e=>ids.has(e.id)).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const focus=orgEntity(f.person);
 return pageHead('PESSOAS E RELAÇÕES','Vínculos dos personagens','Parentescos, encontros, afetos, disputas e relações institucionais confirmados nas fontes.')+`<div class="notice"><strong>Sucessão política não é genealogia.</strong><p>Um sobrenome comum não prova parentesco. Um encontro não prova amizade, e uma aliança não implica concordância permanente. Cada vínculo conserva sua descrição e sua fonte. Este índice seleciona relações confirmadas; a ausência de um vínculo não significa que as pessoas nunca tenham se encontrado.</p></div>
 <form id="relation-filters" class="organization-filters"><div><label for="relation-person">Pessoa ou organização</label><select id="relation-person" name="person"><option value="">Todas as pessoas</option>${options(people.map(e=>[e.id,e.name]),f.person)}</select></div><div><label for="relation-type">Tipo de vínculo</label><select id="relation-type" name="type"><option value="">Todos os vínculos</option>${options([...new Set(allowed.map(r=>r.type))].sort().map(t=>[t,t]),f.type)}</select></div><div><label for="relation-q">Buscar nos vínculos</label><input id="relation-q" name="q" type="search" value="${esc(f.q)}" placeholder="Nome, acontecimento ou período"></div><button class="btn small" type="submit">Aplicar filtros</button><a href="#vinculos">Limpar filtros</a></form>
 ${focus?`<div class="focus-heading"><h2>Relações de ${esc(focus.name)}</h2>${focus.articleId?link(focus.articleId,'Abrir o artigo ↗'):'<p>Nome citado nas fontes; os vínculos podem ser consultados aqui mesmo.</p>'}</div>`:''}<p class="result-count" role="status">${list.length} ${list.length===1?'vínculo encontrado':'vínculos encontrados'}</p>${!spoilers?'<p class="filter-note">Vínculos que revelam os acontecimentos posteriores ao início de 788 permanecem ocultos.</p>':''}<div class="relation-grid">${list.map(r=>relationItem(r,f.person)).join('')}</div>${!list.length?'<div class="empty"><h2>Nenhum vínculo nesta combinação</h2><a href="#vinculos">Limpar filtros</a></div>':''}`;
