function origins(){const groups=[['Antes da contagem',['criacao-virtude','aun','planos','primeira-distancia','confluencia-tres-margens','contenda-primeiro-nome']],['Planos, presenças e caminhos',['noerion','eomundus','virtude-plano','adunevar','mana','descompassos','mnemides','anonimos','velarios']],['Lugares e encontros',['enseada-promessas','patamar-ecos','ishrael','oruven','veyr']],['A interpretação na I Era',['doutrina-tear','talena-ors','edris-vaun','cadernos-permanencia','ensaio-pedra-velada']]];return pageHead('ORIGENS · RECORTES POR ERA','A criação do mundo','Dos relatos primordiais aos estudiosos que procuraram compreendê-los.')+`<figure class="origin-hero"><img src="imagens/v31-criacao-virtude.webp" alt="Interpretação pictórica dos três planos em formação"><figcaption>A criação segundo as tradições de Virtude · fantasia estilizada</figcaption></figure><div class="intro-copy"><p>A Consciência Una associa a origem a Aun e à diferenciação da experiência. Outras tradições, como a Doutrina do Tear, enfatizam os vínculos que compõem a realidade. Os relatos primordiais antecedem a contagem das eras; a investigação de Talena Ors e Edris Vaun pertence à história da I Era.</p><p>Comece por ${link('criacao-virtude','A criação de Virtude')}, siga pelos planos e encontre as tradições nas quais seus habitantes explicam memória, passagem e identidade.</p></div><div class="chips"><a class="chip selected" href="#origens">Criação</a>${['I','II','III'].map(era=>`<a class="chip" href="${era==='I'?'#era/I':'#cronologia?era='+era}">${era} Era${era==='I'?' · recorte':' · cronologia'}</a>`).join('')}<a class="chip" href="#registro">Registro Geral</a></div>${groups.map(([title,ids])=>`<section class="section-head"><h2>${title}</h2></section><div class="origin-grid">${ids.map(id=>{const e=byId(id);return `<a class="panel origin-card" href="#verbete/${id}"><img loading="lazy" src="imagens/${e.image}.webp" alt="${esc(e.imageAlt||e.name)}"><h3>${esc(e.name)}</h3><p>${esc(e.summary)}</p><span class="inline-link">Ler artigo ↗</span></a>`}).join('')}</div>`).join('')}`;}
function lifeDate(v){return v?`${v.approx?'c. ':''}${v.year} da ${v.era} Era`:'Não fixada';}
function lifeYear(v){return v?window.VIRTUDE.successionAudit.eraOffset[v.era]+v.year:null;}
function lifeAge(p,at){if(!p.birth||!at)return 'Não calculável';return `c. ${lifeYear(at)-lifeYear(p.birth)} anos`;}
function lifeBrief(e){const p=e.lifeAudit;return `<section class="life-brief"><span class="eyebrow">VIDA E RESPONSABILIDADES</span><dl><div><dt>Nascimento</dt><dd>${esc(lifeDate(p.birth))}</dd></div><div><dt>Morte</dt><dd>${esc(lifeDate(p.death))}</dd></div><div><dt>Idade nos extremos da atuação</dt><dd>${esc(lifeAge(p,p.activityStart))} → ${esc(lifeAge(p,p.activityEnd))}</dd></div></dl><p>${esc(p.role)}. ${esc(p.transmission)}</p><a class="inline-link" href="#linhagens?q=${encodeURIComponent(p.name)}">Conferir vida, cargo e parentesco ↗</a></section>`;}
function livesPage(ps){
 const data=window.VIRTUDE.successionAudit,group=ps.get('grupo')||'',condition=ps.get('condicao')||'',q=(ps.get('q')||'').trim();
 const exact=data.profiles.some(p=>norm(p.name)===norm(q));
 const list=data.profiles.filter(p=>(!group||p.group===group)&&(!q||(exact?norm(p.name)===norm(q):norm([p.name,p.people,p.role,p.transmission,p.kinship].join(' ')).includes(norm(q))))&&(!condition||condition==='datados'&&p.birth||condition==='lacunas'&&(!p.birth||!p.death)||condition==='eras'&&p.birth&&p.death&&p.birth.era!==p.death.era));
 const groups=[...new Set(data.profiles.map(p=>p.group))];
 return pageHead('CONFERÊNCIA DE CONTINUIDADE','Vidas, cargos e sucessões','Cruze datas pessoais, períodos de atuação e formas de transmissão do poder. Cada perfil leva ao artigo e à sua referência.')+`<div class="intro-copy"><p>${esc(data.yearNote)}</p><p>As datas de um reinado ou de uma guerra delimitam a autoridade e os episódios conhecidos. As funções pessoais, as delegações e os parentescos aparecem separadamente. ${link('linhagens-sucessoes','Ler os critérios e os principais casos ↗')}</p></div><form id="life-filters" class="organization-filters"><div><label for="life-group">Recorte histórico</label><select id="life-group" name="grupo"><option value="">Todos os recortes</option>${options(groups.map(v=>[v,v]),group)}</select></div><div><label for="life-condition">Datas pessoais</label><select id="life-condition" name="condicao">${options([['','Todos os perfis'],['datados','Com nascimento definido'],['lacunas','Com datas em aberto'],['eras','Vidas entre duas eras']],condition)}</select></div><div><label for="life-query">Buscar uma pessoa ou função</label><input type="search" id="life-query" name="q" value="${esc(q)}" placeholder="Nome, comando ou cargo"></div><button class="btn small" type="submit">Aplicar filtros</button><a href="#linhagens">Limpar filtros</a></form><p class="result-count" role="status">${list.length} ${list.length===1?'perfil encontrado':'perfis encontrados'}</p>${list.length?`<div class="life-table-scroll" tabindex="0" role="region" aria-label="Perfis de vidas e sucessões; deslize horizontalmente em telas pequenas"><table class="life-table"><caption>Vidas e transmissões do poder</caption><thead><tr><th scope="col">Pessoa</th><th scope="col">Nascimento e morte</th><th scope="col">Atuação de referência</th><th scope="col">Idades nos extremos</th><th scope="col">Cargo, transmissão e parentesco</th></tr></thead><tbody>${list.map(p=>`<tr><th scope="row">${link(p.articleId,p.name)}<small>${esc(p.people)}<br>${esc(p.group)}</small></th><td><strong>Nascimento</strong><br>${esc(lifeDate(p.birth))}<br><strong>Morte</strong><br>${esc(lifeDate(p.death))}</td><td>${esc(lifeDate(p.activityStart))}<br>até ${esc(lifeDate(p.activityEnd))}<p>${esc(p.role)}</p></td><td>${esc(lifeAge(p,p.activityStart))}<br>até ${esc(lifeAge(p,p.activityEnd))}</td><td><p>${esc(p.transmission)}</p><p>${esc(p.kinship)}</p>${sourceRefs([p.sourceRef])}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Nenhum perfil nesta combinação</h2><a href="#linhagens">Limpar filtros</a></div>'}<div class="reading-actions life-related"><a class="btn outline small" href="#verbete/comandos-primeiro-conflito">Comandos da primeira guerra ↗</a><a class="btn outline small" href="#verbete/casas-reinos-sucessores">Casas e reinos sucessores ↗</a><a class="inline-link" href="#registro?capitulo=67">Conferência no Registro ↗</a></div>`;
}
